"""Reason catalog: every code the sync can show (push item error codes, issue codes, exclusion codes, event codes, cycle/run statuses and reasons, pre-flight findings) -> a plain
title, what happened and what to do next. One place for the read endpoints and the UI; tests/test_reasons.py fails when a code that can be emitted has no entry."""
from typing import TypedDict


class Reason(TypedDict):
    title: str
    explanation: str
    next_step: str


