CATALOG: dict[str, Reason] = {k: {"title": t, "explanation": e, "next_step": n} for k, (t, e, n) in _RAW.items()}
UNKNOWN: Reason = {"title": "Unexpected problem", "explanation": "Something happened that has no description yet.", "next_step": "Give the code shown with it to support."}


def describe(code: str) -> Reason:
    """Catalog entry of a code; `check_failed:<reason>` is described by its reason."""
    return CATALOG.get(code.removeprefix("check_failed:"), UNKNOWN)
